INSERT INTO `configuracion` (`clave`, `valor`, `descripcion`, `updated_at`) VALUES ('agencia_direccion','Av. Javier Prado Este 4600, Santiago de Surco, Lima, Perú','Dirección fiscal / sede','2026-07-01 14:04:21'),('agencia_email','contacto@viajesajt.pe','Correo de contacto general','2026-07-01 14:04:21'),('agencia_facebook','https://facebook.com/viajesajt','URL completa del perfil de Facebook','2026-07-01 14:04:21'),('agencia_horario','Lunes a Viernes: 9:00 AM - 6:00 PM · Sábados: 9:00 AM - 1:00 PM','Horario de atención al público','2026-07-01 14:04:21'),('agencia_instagram','https://instagram.com/viajesajt','URL completa del perfil de Instagram','2026-07-01 14:04:21'),('agencia_latitud','-12.1354','Latitud de la oficina','2026-07-01 14:04:21'),('agencia_longitud','-76.9938','Longitud de la oficina','2026-07-01 14:04:21'),('agencia_mincetur','TC-2024-00123','Registro MINCETUR Tour Operador','2026-07-01 21:48:15'),('agencia_nombre','Viajes AJT','Nombre comercial de la agencia','2026-07-01 14:04:21'),('agencia_razon_social','Viajes AJT Consultores S.A.C.','Razón social registrada','2026-07-01 14:04:21'),('agencia_ruc','20612345678','RUC de la agencia (11 digitos)','2026-07-01 21:48:15'),('agencia_telefono','+51 987 654 321','Teléfono principal de la agencia','2026-07-01 14:04:21'),('agencia_tiktok','','URL completa del perfil de TikTok','2026-07-01 14:04:21'),('agencia_whatsapp','51987654321','Número de WhatsApp sin + ni espacios','2026-07-01 14:04:21'),('agencia_youtube','','URL completa del canal de YouTube','2026-07-01 14:04:21'),('banco_cci','002-123-456789012345-67','Codigo CCI','2026-07-01 21:48:15'),('banco_cuenta','123-4567890123-456','Numero de cuenta','2026-07-01 21:48:15'),('banco_nombre','Banco de Crédito del Perú (BCP)','Nombre del banco','2026-07-01 14:04:21'),('cancelaciones_contenido','<h3>1. Cancelación por parte del cliente</h3>\r\n<table style=\"width:100%;border-collapse:collapse;margin:16px 0\">\r\n<thead>\r\n<tr style=\"border-bottom:2px solid var(--c-border)\">\r\n<th style=\"text-align:left;padding:8px\">Plazo de cancelación</th>\r\n<th style=\"text-align:left;padding:8px\">Reembolso</th>\r\n</tr>\r\n</thead>\r\n<tbody>\r\n<tr style=\"border-bottom:1px solid var(--c-border)\">\r\n<td style=\"padding:8px\">Más de 30 días antes del viaje</td>\r\n<td style=\"padding:8px\">90% del monto pagado</td>\r\n</tr>\r\n<tr style=\"border-bottom:1px solid var(--c-border)\">\r\n<td style=\"padding:8px\">Entre 15 y 30 días antes del viaje</td>\r\n<td style=\"padding:8px\">50% del monto pagado</td>\r\n</tr>\r\n<tr style=\"border-bottom:1px solid var(--c-border)\">\r\n<td style=\"padding:8px\">Menos de 15 días antes del viaje</td>\r\n<td style=\"padding:8px\">Sin reembolso</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n\r\n<h3>2. Cancelación por parte de Viajes AJT</h3>\r\n<p>Si cancelamos un servicio por razones de fuerza mayor o por no alcanzar el mínimo de viajeros, ofrecemos:</p>\r\n<ul>\r\n<li>Cambio de fecha sin costo adicional.</li>\r\n<li>Reembolso del 100% del monto pagado si no hay alternativa aceptable.</li>\r\n</ul>\r\n\r\n<h3>3. No presentación (no-show)</h3>\r\n<p>El no-show en la fecha acordada no genera derecho a reembolso.</p>\r\n\r\n<h3>4. Cambios de reserva</h3>\r\n<p>Los cambios de fecha o destino están sujetos a disponibilidad y posibles diferencias de precio. Consulta con tu asesor antes de solicitar un cambio.</p>\r\n\r\n<h3>5. Seguro de cancelación</h3>\r\n<p>Ofrecemos un seguro de cancelación opcional que cubre imprevistos médicos o personales. Consulta las condiciones al momento de reservar.</p>\r\n\r\n','Contenido HTML de política de cancelación','2026-07-01 21:48:44'),('contacto_email','reservas@viajesajt.pe','Email de contacto para reservas','2026-07-01 14:04:21'),('contacto_telefono','+51 987 654 321','Teléfono de contacto para reservas','2026-07-01 14:04:21'),('contacto_whatsapp','51987654321','WhatsApp de contacto para reservas','2026-07-01 14:04:21'),('dias_anticipacion_reserva','30','Días de anticipación mínima para reservas','2026-07-01 14:04:21'),('libro_reclamaciones_url','','URL del libro de reclamaciones virtual (Ley 29571)','2026-07-01 14:04:21'),('moneda_simbolo','S/','Símbolo de moneda (S/ o $)','2026-07-01 14:04:21'),('plin_numero','921 426 968','Número de Plin','2026-07-01 14:04:21'),('plin_qr_url','','URL del QR de Plin','2026-07-01 14:04:21'),('plin_titular','Viajes AJT Consultores S.A.C.','Titular de Plin','2026-07-01 14:04:21'),('politica_cancelacion','Política de cancelación aplicable a reservas de paquetes turísticos y servicios de asesoría de visa contratados a través de Viajes AJT.','Política de cancelación','2026-07-01 14:04:21'),('privacidad_contenido','<h3>1. Responsable del tratamiento</h3>\r\n<p><strong>Viajes AJT</strong> es responsable del tratamiento de los datos personales recopilados a través de esta plataforma.</p>\r\n\r\n<h3>2. Datos que recopilamos</h3>\r\n<ul>\r\n<li><strong>Datos de identificación:</strong> nombres, apellidos, DNI o pasaporte, correo electrónico, teléfono.</li>\r\n<li><strong>Datos de viaje:</strong> destinos, fechas, preferencias, información de acompañantes.</li>\r\n<li><strong>Datos de pago:</strong> información de transacciones (no almacenamos números de tarjeta).</li>\r\n<li><strong>Datos de navegación:</strong> cookies, dirección IP, dispositivo (solo para mejorar el servicio).</li>\r\n</ul>\r\n\r\n<h3>3. Finalidad del tratamiento</h3>\r\n<p>Utilizamos tus datos para:</p>\r\n<ul>\r\n<li>Gestionar reservas y prestación de servicios contratados.</li>\r\n<li>Realizar trámites de visa cuando aplique.</li>\r\n<li>Enviar confirmaciones, actualizaciones y notificaciones del servicio.</li>\r\n<li>Mejorar la experiencia de navegación y atención al cliente.</li>\r\n</ul>\r\n\r\n<h3>4. Base legal</h3>\r\n<p>El tratamiento se basa en la ejecución del contrato de prestación de servicios y en el consentimiento del titular, conforme a la Ley N.° 29733 — Ley de Protección de Datos Personales del Perú.</p>\r\n\r\n<h3>5. Compartición de datos</h3>\r\n<p>Tus datos pueden ser compartidos con proveedores de servicios (aerolíneas, hoteles, transportistas) estrictamente para la ejecución del servicio contratado. No vendemos ni cedemos datos a terceros con fines comerciales.</p>\r\n\r\n<h3>6. Derechos del titular</h3>\r\n<p>Puedes ejercer tus derechos de acceso, rectificación, eliminación y oposición contactándonos a <a href=\"mailto:contacto@viajesajt.pe\">contacto@viajesajt.pe</a>.</p>\r\n\r\n<h3>7. Seguridad</h3>\r\n<p>Implementamos medidas técnicas y organizativas para proteger tus datos contra acceso no autorizado, pérdida o alteración.</p>\r\n\r\n<h3>8. Cookies</h3>\r\n<p>Utilizamos cookies esenciales para el funcionamiento de la plataforma. Puedes gestionar las cookies desde la configuración de tu navegador.</p>\r\n\r\n','Contenido HTML de política de privacidad','2026-07-01 21:48:44'),('terminos_condiciones','Términos y condiciones aplicables a la contratación de servicios turísticos y de asesoría de visa a través de la plataforma de Viajes AJT.','Texto de términos y condiciones','2026-07-01 14:04:21'),('terminos_contenido','<h3>1. Información de la empresa</h3>\r\n<p><strong>Viajes AJT</strong> es una agencia de viajes y asesoría de visas constituida bajo las leyes de la República del Perú. Nuestro RUC y datos de contacto se encuentran disponibles en esta plataforma.</p>\r\n\r\n<h3>2. Servicios ofrecidos</h3>\r\n<p>Viajes AJT ofrece la intermediación en la contratación de paquetes turísticos nacionales e internacionales, así como asesoría y acompañamiento en trámites de visa. Los servicios están sujetos a disponibilidad y a las condiciones de cada proveedor.</p>\r\n\r\n<h3>3. Reservas y pagos</h3>\r\n<ul>\r\n<li>Las reservas se confirman únicamente tras la recepción del pago correspondiente.</li>\r\n<li>Los precios publicados incluyen los impuestos aplicables salvo indicación contraria.</li>\r\n<li>El medio y plazo de pago se indican durante el proceso de checkout.</li>\r\n</ul>\r\n\r\n<h3>4. Modificaciones y cancelaciones</h3>\r\n<p>Las modificaciones a una reserva confirmada están sujetas a disponibilidad y posibles diferencias de precio. Para cancelaciones, se aplica la <a href=\"<?= BASE_URL ?>/cancelaciones\">Política de Cancelación</a>.</p>\r\n\r\n<h3>5. Responsabilidad</h3>\r\n<p>Viajes AJT actúa como intermediario entre el cliente y los proveedores de servicios (aerolíneas, hoteles, transportistas). No nos responsabilizamos por cancelaciones, retrasos o cambios realizados directamente por los proveedores, aunque haremos todo lo posible para asistirte.</p>\r\n\r\n<h3>6. Documentación del viajero</h3>\r\n<p>El cliente es responsable de contar con la documentación requerida (pasaporte vigente, visa, vacunas, etc.) para el destino contratado. Viajes AJT no se hace responsable por la denegación de entradas por parte de autoridades migratorias.</p>\r\n\r\n<h3>7. Protección de datos</h3>\r\n<p>El tratamiento de datos personales se rige por nuestra <a href=\"<?= BASE_URL ?>/privacidad\">Política de Privacidad</a>.</p>\r\n\r\n<h3>8. Legislación aplicable</h3>\r\n<p>Estos términos se rigen por las leyes de la República del Perú. Cualquier controversia será resuelta ante los tribunales competentes de Lima, Perú.</p>\r\n\r\n','Contenido HTML de términos y condiciones','2026-07-01 21:48:44'),('testimonios_habilitado','1','Habilitar/ocultar sección de testimonios (1=visible, 0=oculto)','2026-07-01 14:04:21'),('yape_numero','921 426 968','Número de Yape','2026-07-01 14:04:21'),('yape_qr_url','assets/img/QR/yape.jpg','Ruta del QR de Yape','2026-07-01 14:04:21'),('yape_titular','Viajes AJT Consultores S.A.C.','Titular de Yape','2026-07-01 14:04:21');
