INSERT INTO `paquetes` (`id_paquete`, `id_categoria`, `id_ciudad`, `nombre`, `slug`, `descripcion_corta`, `descripcion`, `itinerario`, `precio_base`, `precio_anterior`, `duracion_dias`, `duracion_noches`, `cupo_maximo`, `dificultad`, `hotel`, `habitacion`, `comidas`, `vuelos`, `movilidad`, `guia`, `destacado`, `disponible`) VALUES (1,1,1,'Cusco, Valle Sagrado & Machu Picchu','cusco-valle-sagrado-machu-picchu','Circuito cultural por Cusco, Valle Sagrado y Machu Picchu con tren turístico y guía local.','Una experiencia auténtica por el corazón del Imperio Inca. Vuela a Cusco, recorre el Valle Sagrado y descubre Machu Picchu en tren panorámico, todo con guía local en español y traslados privados.','[{\"dia\":1,\"titulo\":\"Llegada a Cusco\",\"descripcion\":\"Traslado del aeropuerto al hotel. Tarde libre para aclimatación.\"},{\"dia\":2,\"titulo\":\"City Tour Cusco\",\"descripcion\":\"Recorrido por la Catedral, Qoricancha, Sacsayhuamán y Tambomachay.\"},{\"dia\":3,\"titulo\":\"Valle Sagrado\",\"descripcion\":\"Visita a Pisac, Ollantaytambo y Chinchero. Almuerzo incluido.\"},{\"dia\":4,\"titulo\":\"Machu Picchu\",\"descripcion\":\"Tren panorámico a Aguas Calientes. Tour guiado por la ciudadela. Retorno a Cusco.\"},{\"dia\":5,\"titulo\":\"Retorno\",\"descripcion\":\"Mañana libre para compras. Traslado al aeropuerto.\"}]',1290.00,1490.00,5,4,18,'Moderada','Hotel boutique 3★ superior en centro histórico de Cusco','Habitación doble estándar','Desayunos diarios y almuerzo buffet en Valle Sagrado','Vuelos Lima–Cusco–Lima no incluidos','Traslados aeropuerto, estaciones y excursiones en servicio turístico','Guía oficial bilingüe en excursiones principales',1,1),(2,2,2,'Cancún All Inclusive','cancun-all-inclusive','Vacaciones de playa en Cancún con resort all inclusive y traslados privados.','Descansa frente al Caribe con resort todo incluido, traslados, asistencia y una excursión cultural a Chichén Itzá para combinar playa, historia y comodidad.','[{\"dia\":1,\"titulo\":\"Llegada a Cancún\",\"descripcion\":\"Recepción en aeropuerto. Traslado al resort all inclusive. Tarde libre en la playa.\"},{\"dia\":2,\"titulo\":\"Chichén Itzá\",\"descripcion\":\"Excursión guiada a la zona arqueológica y cenote. Retorno al resort.\"},{\"dia\":3,\"titulo\":\"Isla Mujeres\",\"descripcion\":\"Navegación a la isla. Recorrido, playa Norte y snorkel. Retorno al resort.\"},{\"dia\":4,\"titulo\":\"Playa y descanso\",\"descripcion\":\"Día libre en el resort: piscina, playa y actividades incluidas.\"},{\"dia\":5,\"titulo\":\"Retorno\",\"descripcion\":\"Último desayuno. Traslado al aeropuerto.\"}]',1450.00,1650.00,7,6,24,'Baja','Resort all inclusive 4★ en zona hotelera de Cancún','Habitación doble vista jardín o laguna','Plan todo incluido en el resort','Vuelos internacionales no incluidos','Traslados privados aeropuerto-hotel-aeropuerto','Asistencia local en destino y coordinación 24/7',1,1),(3,3,3,'Patagonia Argentina','patagonia-argentina','Ruta escénica por glaciares y montañas de la Patagonia argentina.','Viaje para amantes de la naturaleza: glaciares, montañas, caminatas y paisajes del sur argentino con vuelos internos y excursiones guiadas.','[{\"dia\":1,\"titulo\":\"Llegada a El Calafate\",\"descripcion\":\"Vuelo internacional. Traslado al hotel. Tarde libre.\"},{\"dia\":2,\"titulo\":\"Glaciar Perito Moreno\",\"descripcion\":\"Excursión completa al glaciar: pasarelas y observación de desprendimientos.\"},{\"dia\":3,\"titulo\":\"Navegación y glaciares\",\"descripcion\":\"Barco por el Lago Argentino. Glaciares Spegazzini y Upsala.\"},{\"dia\":4,\"titulo\":\"Ushuaia y Tierra del Fuego\",\"descripcion\":\"Vuelo a Ushuaia. Visita al Parque Nacional. Canal Beagle.\"},{\"dia\":5,\"titulo\":\"Retorno\",\"descripcion\":\"Vuelo de regreso Ushuaia → Lima.\"}]',1850.00,NULL,9,8,14,'Moderada','Hoteles 3★ en El Calafate y Ushuaia','Habitación doble estándar con calefacción','Desayunos diarios','Vuelos internacionales e internos no incluidos','Traslados regulares y excursiones compartidas','Guías locales especializados en parques nacionales',0,1),(4,2,4,'Capitales Europeas','capitales-europeas','Recorrido urbano por Madrid, París, Roma y Ámsterdam con conexiones coordinadas.','Recorre las capitales más buscadas de Europa con hoteles céntricos, guía en español, traslados y visitas panorámicas incluidas.',NULL,2400.00,2650.00,12,11,28,'Baja','Hoteles 3★/4★ bien conectados por transporte público','Habitación doble estándar','Desayunos diarios','Vuelo intercontinental no incluido; conexiones internas cotizadas aparte','Traslados y trenes/vuelos internos según programa final','Guía acompañante o local en visitas panorámicas seleccionadas',1,1),(5,2,5,'Japón Esencial','japon-esencial','Japón esencial entre Tokio, Kioto y Osaka con asistencia para primer viaje.','Descubre Japón con un recorrido equilibrado entre modernidad, templos, gastronomía y experiencias culturales, incluyendo JR Pass y asistencia local.','[{\"dia\":1,\"titulo\":\"Llegada a Tokio\",\"descripcion\":\"Traslado al hotel. Shibuya, Senso-ji y Akihabara.\"},{\"dia\":2,\"titulo\":\"Kioto\",\"descripcion\":\"Shinkansen a Kioto. Templos Fushimi Inari y Kinkaku-ji.\"},{\"dia\":3,\"titulo\":\"Osaka\",\"descripcion\":\"Castillo de Osaka, Dotonbori y degustación de street food.\"},{\"dia\":4,\"titulo\":\"Nara y Tokio\",\"descripcion\":\"Excursión a Nara. Retorno a Tokio. Compras en Akihabara.\"},{\"dia\":5,\"titulo\":\"Retorno\",\"descripcion\":\"Traslado al aeropuerto. Vuelo de regreso a Lima.\"}]',3100.00,NULL,10,9,16,'Moderada','Hoteles urbanos 3★ cerca de estaciones principales','Habitación twin compacta estilo japonés moderno','Desayunos diarios','Vuelos internacionales no incluidos','Tarjetas o pases de tren según ruta confirmada','Guía local en visitas clave y asistencia remota',0,1),(6,2,6,'Cartagena Romántica','cartagena-romantica','Escapada romántica a Cartagena con centro histórico, playa y experiencia al atardecer.','Escapada al Caribe colombiano con centro histórico, Islas del Rosario y cena al atardecer, ideal para parejas o viajes cortos.','[{\"dia\":1,\"titulo\":\"Llegada a Cartagena\",\"descripcion\":\"Recepción. Traslado al hotel en zona amurallada. Tarde libre.\"},{\"dia\":2,\"titulo\":\"Centro histórico\",\"descripcion\":\"Caminata: Castillo San Felipe, murallas y mirador. Cena romántica.\"},{\"dia\":3,\"titulo\":\"Islas del Rosario\",\"descripcion\":\"Lancha a las islas. Snorkel y almuerzo en isla privada.\"},{\"dia\":4,\"titulo\":\"Retorno\",\"descripcion\":\"Paseo libre por Getsemaní. Traslado al aeropuerto.\"}]',780.00,890.00,4,3,12,'Baja','Hotel boutique 3★/4★ en zona amurallada o Bocagrande','Habitación doble matrimonial','Desayunos diarios y una cena especial','Vuelos internacionales no incluidos','Traslados privados aeropuerto-hotel-aeropuerto','Guía local para caminata histórica',0,1),(7,2,7,'Orlando Familiar','orlando-familiar','Viaje familiar a Orlando con parques, traslados y planificación diaria asistida.','Paquete familiar con parques temáticos, traslados privados, hotel cómodo y asistencia para disfrutar Disney y Universal sin complicaciones.','[{\"dia\":1,\"titulo\":\"Llegada a Orlando\",\"descripcion\":\"Recepción. Traslado al hotel familiar. Tarde libre.\"},{\"dia\":2,\"titulo\":\"Magic Kingdom\",\"descripcion\":\"Día completo: Space Mountain, Pirates, desfiles y fuegos artificiales.\"},{\"dia\":3,\"titulo\":\"Universal Studios\",\"descripcion\":\"Día completo: Harry Potter, Jurassic World y CityWalk.\"},{\"dia\":4,\"titulo\":\"Epcot o playa\",\"descripcion\":\"Opción A: Epcot World Showcase. Opción B: Cocoa Beach.\"},{\"dia\":5,\"titulo\":\"Retorno\",\"descripcion\":\"Último desayuno. Traslado al aeropuerto.\"}]',2200.00,2450.00,8,7,20,'Baja','Hotel familiar 3★ superior cerca de parques o International Drive','Habitación doble con dos camas queen','Desayunos según hotel confirmado','Vuelos internacionales no incluidos','Traslados privados y shuttle del hotel sujeto a disponibilidad','Asistencia para planificación de parques y reservas',1,1),(8,3,8,'Huaraz — Laguna 69','huaraz-laguna-69','Aventura andina en Huaraz con Laguna 69, Pastoruri y cultura regional.','Una ruta de trekking por paisajes andinos, Laguna 69, Pastoruri y Chavín de Huántar, pensada para viajeros de aventura.','[{\"dia\":1,\"titulo\":\"Viaje a Huaraz\",\"descripcion\":\"Salida desde Lima. Llegada y tarde libre en la ciudad.\"},{\"dia\":2,\"titulo\":\"Laguna 69\",\"descripcion\":\"Trekking completo a la Laguna 69. Box lunch incluido.\"},{\"dia\":3,\"titulo\":\"Pastoruri y Chavín\",\"descripcion\":\"Visita al nevado Pastoruri y sitio arqueológico de Chavín.\"},{\"dia\":4,\"titulo\":\"Retorno a Lima\",\"descripcion\":\"Mañana libre. Retorno en bus turístico.\"}]',690.00,NULL,4,3,15,'Alta','Hotel turístico 3★ en Huaraz','Habitación doble estándar','Desayunos diarios y box lunch para Laguna 69','No aplica; salida terrestre desde Lima opcional','Movilidad turística compartida para excursiones','Guía local de montaña para caminatas programadas',0,1),(9,1,9,'Arequipa y Cañón del Colca','arequipa-canon-del-colca','Ciudad blanca y uno de los cañones más profundos del mundo.','Recorre Arequipa, sus conventos y el Valle del Colca con avistamiento de cóndores, aguas termales y pueblos andinos.','[{\"dia\":1,\"titulo\":\"Llegada a Arequipa\",\"descripcion\":\"City tour por el centro histórico y convento de Santa Catalina.\"},{\"dia\":2,\"titulo\":\"Cañón del Colca\",\"descripcion\":\"Viaje al Valle del Colca. Aguas termales y pueblos andinos.\"},{\"dia\":3,\"titulo\":\"Cóndores y retorno\",\"descripcion\":\"Mirador de los Cóndores. Retorno a Arequipa.\"}]',650.00,750.00,3,2,16,'Moderada','Hotel 3★ en centro histórico de Arequipa','Habitación doble','Desayunos diarios y almuerzo en el Colca','No incluido','Movilidad turística','Guía local bilingüe',0,1),(10,1,10,'Máncora Beach Escape','mancora-beach-escape','Playa, sol y surf en el norte del Perú.','Escapada tropical a Máncora con hotel frente al mar, piscina, deportes acuáticos y vida nocturna.','[{\"dia\":1,\"titulo\":\"Llegada a Máncora\",\"descripcion\":\"Traslado al hotel. Tarde de playa.\"},{\"dia\":2,\"titulo\":\"Playa y surf\",\"descripcion\":\"Día libre en la playa. Clase de surf opcional.\"},{\"dia\":3,\"titulo\":\"Descanso\",\"descripcion\":\"Piscina, lectura y atardecer en la playa.\"},{\"dia\":4,\"titulo\":\"Retorno\",\"descripcion\":\"Traslado de salida.\"}]',580.00,NULL,4,3,20,'Baja','Hotel boutique frente al mar','Habitación doble vista al mar','Desayuno diario','No incluido','Traslados privados','Asistencia local',0,1),(11,3,11,'Tarapoto Aventura','tarapoto-aventura','Selva, lagunas y cascadas en la selva alta.','Aventura amazónica con visitas a la Laguna Azul, cascadas de Ahuashiyacu, paseos en bote y gastronomía regional.','[{\"dia\":1,\"titulo\":\"Llegada a Tarapoto\",\"descripcion\":\"Recepción. Visita a la Laguna Azul.\"},{\"dia\":2,\"titulo\":\"Cascadas\",\"descripcion\":\"Excursión a cascadas de Ahuashiyacu y paseo en bote.\"},{\"dia\":3,\"titulo\":\"Selva\",\"descripcion\":\"Caminata por la selva y avistamiento de fauna.\"},{\"dia\":4,\"titulo\":\"Retorno\",\"descripcion\":\"Traslado al aeropuerto.\"}]',720.00,NULL,4,3,14,'Moderada','Lodge turístico 3★','Habitación doble','Desayunos y almuerzos','No incluido','Movilidad turística compartida','Guía de selva',1,1),(12,3,12,'Iquitos Amazonía','iquitos-amazonia','Expedición al corazón del Amazonas peruano.','Navega por el río Amazonas, visita comunidades nativas, avista fauna silvestre y duerme en lodge amazónico.','[{\"dia\":1,\"titulo\":\"Llegada a Iquitos\",\"descripcion\":\"Vuelo desde Lima. Navegación río Amazonas al lodge.\"},{\"dia\":2,\"titulo\":\"Comunidades\",\"descripcion\":\"Visita a comunidades nativas y artesanías.\"},{\"dia\":3,\"titulo\":\"Fauna silvestre\",\"descripcion\":\"Avistamiento de delfines rosados y monos.\"},{\"dia\":4,\"titulo\":\"Selva profunda\",\"descripcion\":\"Caminata nocturna por la selva.\"},{\"dia\":5,\"titulo\":\